237	// decodeObject decodes exactly one JSON object and rejects unknown fields,
238	// trailing content and non-object bodies.
239	func decodeObject(body []byte, target any) error {
240		trimmed := bytes.TrimSpace(body)
241		if len(trimmed) == 0 || trimmed[0] != '{' {
242			return ValidationError("request body must be a JSON object")
243		}
244		decoder := json.NewDecoder(bytes.NewReader(trimmed))
245		decoder.DisallowUnknownFields()
246		decoder.UseNumber()
247		if err := decoder.Decode(target); err != nil {
248			return ValidationError(
249				"request body does not match the documented schema: %s",
250				strings.TrimPrefix(err.Error(), "json: "),
251			)
252		}
253		if _, err := decoder.Token(); err != io.EOF {
254			return ValidationError("request body must contain exactly one JSON object")
255		}
256		return nil
257	}
258	
259	// encodeResponse renders a response as canonical JSON.
260	func encodeResponse(value any) (string, error) {
261		encoded, err := json.Marshal(value)
262		if err != nil {
263			return "", InternalError("response could not be encoded: %s", err)
264		}
265		return string(encoded), nil
266	}
267	
268	// decodeResponse restores a stored response without losing integer precision.
269	func decodeResponse(encoded string) (any, error) {
270		decoder := json.NewDecoder(strings.NewReader(encoded))
271		decoder.UseNumber()
272		var value any
273		if err := decoder.Decode(&value); err != nil {
274			return nil, InternalError("stored response could not be decoded: %s", err)
275		}
276		return value, nil
277	}
278	
279	// normalizeResponse turns any response value into its canonical JSON shape so a
280	// replayed idempotent request returns byte-identical JSON.
281	func normalizeResponse(value any) (any, error) {
282		encoded, err := encodeResponse(value)
283		if err != nil {
284			return nil, err
285		}
286		return decodeResponse(encoded)
287	}
288	
289	func validateIdentifier(value, field string) (string, error) {
290		if value == "" {
291			return "", ValidationError("%s is required", field)
292		}
293		if len(value) > maxIdentifierLength {
294			return "", ValidationError("%s must be at most %d characters", field, maxIdentifierLength)
295		}
296		for index := 0; index < len(value); index++ {
297			if value[index] < 0x21 || value[index] > 0x7e {
298				return "", ValidationError("%s must contain printable ASCII characters without whitespace", field)
299			}
300		}
301		return value, nil
302	}
303	
304	func validateText(value, field string) (string, error) {
305		if len(value) > maxTextLength {
306			return "", ValidationError("%s must be at most %d characters", field, maxTextLength)
307		}
308		for _, character := range value {
309			if character < 0x20 || character == 0x7f {
310				return "", ValidationError("%s must not contain control characters", field)
311			}
312		}
313		return value, nil
314	}
315	
316	func validateDate(value, field string) (string, error) {
317		parsed, err := time.Parse(dateLayout, value)
318		if err != nil || parsed.Format(dateLayout) != value {
319			return "", ValidationError("%s must be an ISO 8601 calendar date (YYYY-MM-DD)", field)
320		}
321		return value, nil
322	}
323	
324	func validateCurrency(value, field string, required bool) (string, error) {
325		if value == "" {
326			if required {
327				return "", ValidationError("%s is required", field)
328			}
329			return "", nil
330		}
331		if len(value) != 3 {
332			return "", ValidationError("%s must be a three letter uppercase ISO 4217 currency code", field)
333		}
334		for index := 0; index < 3; index++ {
335			if value[index] < 'A' || value[index] > 'Z' {
336				return "", ValidationError("%s must be a three letter uppercase ISO 4217 currency code", field)
337			}
338		}
339		return value, nil
340	}
341	
342	func validateAmount(value int64, field string, allowZero, allowNegative bool) (int64, error) {
343		if value > maxAmountMinor || value < -maxAmountMinor {
344			return 0, ValidationError("%s must be at most %d minor units in magnitude", field, maxAmountMinor)
345		}
346		if value == 0 && !allowZero {
347			return 0, ValidationError("%s must not be zero", field)
348		}
349		if value < 0 && !allowNegative {
350			return 0, ValidationError("%s must not be negative", field)
351		}
352		return value, nil
353	}
354	
355	// parseRateFraction converts an exact decimal string into a positive reduced
356	// fraction. Exponent notation, signs and more than nine decimals are rejected.
357	func parseRateFraction(value, field string) (int64, int64, error) {
358		invalid := ValidationError("%s must be a positive decimal number such as 7.2450", field)
359		if value == "" {
360			return 0, 0, ValidationError("%s is required", field)
361		}
362		whole, fraction, _ := strings.Cut(value, ".")
363		if strings.Contains(fraction, ".") {
364			return 0, 0, invalid
365		}
366		digits := whole + fraction
367		if digits == "" {
368			return 0, 0, invalid
369		}
370		for index := 0; index < len(digits); index++ {
371			if digits[index] < '0' || digits[index] > '9' {
372				return 0, 0, invalid
373			}
374		}
375		if len(fraction) > maxRateDecimals {
376			return 0, 0, ValidationError("%s must have at most %d decimal places", field, maxRateDecimals)
377		}
378		if len(digits) > maxRateDigits {
379			return 0, 0, ValidationError("%s must have at most %d digits", field, maxRateDigits)
380		}
381		numerator, err := strconv.ParseInt(digits, 10, 64)
382		if err != nil {
383			return 0, 0, invalid
384		}
385		if numerator <= 0 {
386			return 0, 0, ValidationError("%s must be greater than zero", field)
387		}
388		denominator := pow10(len(fraction))
389		divisor := greatestCommonDivisor(numerator, denominator)
390		return numerator / divisor, denominator / divisor, nil
391	}
392	
393	// convertMinor multiplies a minor amount by an exact fraction and rounds half
394	// away from zero, which is the only rounding rule ReconCore uses.
395	func convertMinor(amount, numerator, denominator int64) (int64, error) {
396		if denominator <= 0 || numerator <= 0 {
397			return 0, InternalError("exchange rate fraction is invalid")
398		}
399		product := new(big.Int).Mul(big.NewInt(amount), big.NewInt(numerator))
400		divisor := big.NewInt(denominator)
401		quotient := new(big.Int)
402		remainder := new(big.Int)
403		quotient.QuoRem(product, divisor, remainder)
404		doubled := new(big.Int).Abs(remainder)
405		doubled.Lsh(doubled, 1)
406		if doubled.Cmp(divisor) >= 0 {
407			if quotient.Sign() < 0 {
408				quotient.Sub(quotient, big.NewInt(1))
409			} else {
410				quotient.Add(quotient, big.NewInt(1))
411			}
412		}
413		if !quotient.IsInt64() {
414			return 0, ValidationError("converted amount is outside the supported range")
415		}
416		return quotient.Int64(), nil
417	}
418	
419	func pow10(exponent int) int64 {
420		value := int64(1)
421		for index := 0; index < exponent; index++ {
422			value *= 10
423		}
424		return value
425	}
426	
427	func greatestCommonDivisor(left, right int64) int64 {
428		for right != 0 {
429			left, right = right, left%right
430		}
431		return left
432	}
433

