309	// CreateRate stores one exchange rate snapshot.
310	func (s *Service) CreateRate(body []byte, key string) (any, error) {
311		var request createRateRequest
312		if err := decodeObject(body, &request); err != nil {
313			return nil, err
314		}
315		base, err := validateCurrency(request.Base, "base", true)
316		if err != nil {
317			return nil, err
318		}
319		quote, err := validateCurrency(request.Quote, "quote", true)
320		if err != nil {
321			return nil, err
322		}
323		if base == quote {
324			return nil, ValidationError("base and quote must be different currencies")
325		}
326		date, err := validateDate(request.Date, "date")
327		if err != nil {
328			return nil, err
329		}
330		numerator, denominator, err := parseRateFraction(request.Rate, "rate")
331		if err != nil {
332			return nil, err
333		}
334		return s.runIdempotent(key, fmt.Sprintf("create-rate:%s/%s/%s", base, quote, date), func(state *State) (any, error) {
335			for _, existing := range state.Rates {
336				if existing.Base == base && existing.Quote == quote && existing.Date == date {
337					return nil, ConflictError("a %s/%s rate for %s already exists", base, quote, date)
338				}
339			}
340			rate := &Rate{
341				Base:        base,
342				Quote:       quote,
343				Date:        date,
344				Rate:        request.Rate,
345				Numerator:   numerator,
346				Denominator: denominator,
347				CreatedAt:   s.now(),
348			}
349			state.Rates = append(state.Rates, rate)
350			return rate, nil
351		})
352	}
