361	type journalLineRequest struct {
362		AccountID   string `json:"account_id"`
363		Side        string `json:"side"`
364		AmountMinor int64  `json:"amount_minor"`
365		Currency    string `json:"currency"`
366		Rate        string `json:"rate"`
