370	type createJournalRequest struct {
371		ID    string                `json:"id"`
372		Date  string                `json:"date"`
373		Memo  string                `json:"memo"`
374		Lines []*journalLineRequest `json:"lines"`
375	}
376	
377	// CreateJournal posts an immutable voucher once it balances in the functional
378	// currency. A date inside a closed period is rejected.
379	func (s *Service) CreateJournal(body []byte, key string) (any, error) {
380		var request createJournalRequest
381		if err := decodeObject(body, &request); err != nil {
382			return nil, err
383		}
384		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
385		if err != nil {
386			return nil, err
387		}
388		return s.runIdempotent(key, "create-journal:"+id, func(state *State) (any, error) {
389			if _, found := state.Journals[id]; found {
390				return nil, ConflictError("journal %s already exists", id)
391			}
392			if closedPeriodFor(state, date) != nil {
393				return nil, ConflictError("closed period rejects journal")
394			}
395			journal, err := s.buildJournal(state, &request, id, date, memo)
396			if err != nil {
397				return nil, err
398			}
399			state.Journals[id] = journal
400			return journal, nil
401		})
402	}
403	
404	// validateJournalHead checks the journal fields that do not depend on the
405	// stored state and returns them normalized.
406	func validateJournalHead(rawID, rawDate, rawMemo string, lineCount int) (string, string, string, error) {
407		id, err := validateIdentifier(rawID, "journal id")
408		if err != nil {
409			return "", "", "", err
410		}
411		date, err := validateDate(rawDate, "date")
412		if err != nil {
413			return "", "", "", err
414		}
415		memo, err := validateText(rawMemo, "memo")
416		if err != nil {
417			return "", "", "", err
418		}
419		if lineCount < 2 {
420			return "", "", "", ValidationError("lines must contain at least two postings")
421		}
422		return id, date, memo, nil
423	}
424	
425	// buildJournal resolves every line and freezes the balanced voucher. The
426	// caller owns the duplicate-id and closed-period policy.
427	func (s *Service) buildJournal(state *State, request *createJournalRequest, id, date, memo string) (*Journal, error) {
428		journal := &Journal{
429			ID:                 id,
430			Date:               date,
431			Memo:               memo,
432			FunctionalCurrency: s.functionalCurrency,
433			Lines:              []*JournalLine{},
434			CreatedAt:          s.now(),
435		}
436		var debits, credits int64
437		for position, raw := range request.Lines {
438			line, err := s.buildJournalLine(state, raw, position+1, date)
439			if err != nil {
440				return nil, err
441			}
442			if line.Side == "debit" {
443				debits += line.FunctionalAmountMinor
444			} else {
445				credits += line.FunctionalAmountMinor
446			}
447			journal.Lines = append(journal.Lines, line)
448		}
449		if debits != credits {
450			return nil, ValidationError(
451				"journal is not balanced in %s: debits %d, credits %d",
452				s.functionalCurrency, debits, credits,
453			)
454		}
455		journal.DebitFunctionalMinor = debits
456		journal.CreditFunctionalMinor = credits
457		return journal, nil
458	}
459	
460	// closedPeriodFor returns the close that covers date, or nil when the date
461	// falls in an open period.
462	func closedPeriodFor(state *State, date string) *PeriodClose {
463		for _, close := range state.PeriodCloses {
464			if close.Period.Start <= date && date <= close.Period.End {
465				return close
466			}
467		}
468		return nil
469	}
470	
471	// GetJournal returns one stored voucher.
472	func (s *Service) GetJournal(id string) (any, error) {
473		return s.store.View(func(state *State) (any, error) {
474			journal, found := state.Journals[id]
475			if !found {
476				return nil, NotFoundError("journal %s was not found", id)
477			}
478			return journal, nil
479		})
480	}
481	
482	type createPeriodCloseRequest struct {
483		ID     string        `json:"id"`
484		Period periodRequest `json:"period"`
485	}
486	
487	// CreatePeriodClose freezes one calendar month. The period must be exactly one
488	// natural month and no other close may cover the same month.
489	func (s *Service) CreatePeriodClose(body []byte, key string) (any, error) {
490		var request createPeriodCloseRequest
491		if err := decodeObject(body, &request); err != nil {
492			return nil, err
493		}
494		if _, err := validateIdentifier(request.ID, "period close id"); err != nil {
495			return nil, ValidationError("invalid period close id")
496		}
497		id := request.ID
498		start, err := validatePeriodCloseDate(request.Period.Start)
499		if err != nil {
500			return nil, err
501		}
502		end, err := validatePeriodCloseDate(request.Period.End)
503		if err != nil {
504			return nil, err
505		}
506		if !isCalendarMonth(start, end) {
507			return nil, ValidationError("period is not one calendar month")
508		}
509		return s.runIdempotent(key, "create-period-close:"+id, func(state *State) (any, error) {
510			if _, found := state.PeriodCloses[id]; found {
511				return nil, ConflictError("period close exists")
512			}
513			for _, existing := range state.PeriodCloses {
514				if existing.Period.Start[:7] == start[:7] {
515					return nil, ConflictError("calendar month is closed")
516				}
517			}
518			close := &PeriodClose{
519				ID:                   id,
520				Period:               Period{Start: start, End: end},
521				Status:               "closed",
522				ClosedAt:             s.now(),
523				AdjustmentCount:      0,
524				AdjustmentJournalIDs: []string{},
525			}
526			state.PeriodCloses[id] = close
527			return close, nil
528		})
529	}
530	
531	// validatePeriodCloseDate applies the public YYYY-MM-DD rule under the period
532	// close message.
533	func validatePeriodCloseDate(value string) (string, error) {
534		if _, err := validateDate(value, "period date"); err != nil {
535			return "", ValidationError("invalid period date")
536		}
537		return value, nil
538	}
539	
540	// isCalendarMonth reports whether start and end together span exactly one
541	// natural month, first day to last day.
542	func isCalendarMonth(start, end string) bool {
543		first, err := time.Parse(dateLayout, start)
544		if err != nil || first.Day() != 1 {
545			return false
546		}
547		last, err := time.Parse(dateLayout, end)
548		if err != nil {
549			return false
550		}
551		return last.Equal(first.AddDate(0, 1, -1))
552	}
