565	// CreateAdjustment posts an adjustment journal into a closed period through
566	// its close. The voucher follows every ordinary journal rule and additionally
567	// requires a memo and a date inside the closed period.
568	func (s *Service) CreateAdjustment(closeID string, body []byte, key string) (any, error) {
569		var request createJournalRequest
570		if err := decodeObject(body, &request); err != nil {
571			return nil, err
572		}
573		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
574		if err != nil {
575			return nil, err
576		}
577		return s.runIdempotent(key, "create-adjustment:"+closeID+":"+id, func(state *State) (any, error) {
578			close, found := state.PeriodCloses[closeID]
579			if !found {
580				return nil, NotFoundError("period close not found")
581			}
582			if memo == "" {
583				return nil, ValidationError("adjustment memo required")
584			}
585			if date < close.Period.Start || date > close.Period.End {
586				return nil, ValidationError("adjustment date outside period")
587			}
588			if _, found := state.Journals[id]; found {
589				return nil, ConflictError("journal exists")
590			}
591			journal, err := s.buildJournal(state, &request, id, date, memo)
592			if err != nil {
593				return nil, err
594			}
595			state.Journals[id] = journal
596			close.AdjustmentJournalIDs = append(close.AdjustmentJournalIDs, id)
597			close.AdjustmentCount = len(close.AdjustmentJournalIDs)
598			return journal, nil
599		})
600	}
