602	func (s *Service) buildJournalLine(state *State, raw *journalLineRequest, index int, date string) (*JournalLine, error) {
603		if raw == nil {
604			return nil, ValidationError("lines[%d] must be an object", index)
605		}
606		accountID, err := validateIdentifier(raw.AccountID, fmt.Sprintf("lines[%d].account_id", index))
607		if err != nil {
608			return nil, err
609		}
610		account, found := state.Accounts[accountID]
611		if !found {
612			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
613		}
614		if raw.Side != "debit" && raw.Side != "credit" {
615			return nil, ValidationError("lines[%d].side must be debit or credit", index)
616		}
617		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
618		if err != nil {
619			return nil, err
620		}
621		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
622		if err != nil {
623			return nil, err
624		}
625		if currency == "" {
626			currency = account.Currency
627		}
628		if currency != account.Currency {
629			return nil, ValidationError(
630				"lines[%d].currency %s must match the currency %s of account %s",
631				index, currency, account.Currency, accountID,
632			)
633		}
634		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
635		if err != nil {
636			return nil, err
637		}
638		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
639		if err != nil {
640			return nil, err
641		}
642		functional, err := convertMinor(amount, numerator, denominator)
643		if err != nil {
644			return nil, err
645		}
646		if functional < 1 {
647			return nil, ValidationError(
648				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
649				index, s.functionalCurrency,
650			)
651		}
652		return &JournalLine{
653			Index:                 index,
654			AccountID:             accountID,
655			Side:                  raw.Side,
656			AmountMinor:           amount,
657			Currency:              currency,
658			Rate:                  raw.Rate,
659			RateNumerator:         numerator,
660			RateDenominator:       denominator,
661			RateSource:            source,
662			FunctionalAmountMinor: functional,
663			Reference:             reference,
664		}, nil
665	}
