667	// resolveRate returns the exact fraction that converts one minor unit of
668	// currency into the functional currency for the given date.
669	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
670		if currency == s.functionalCurrency {
671			if declared == "" || declared == "1" {
672				return 1, 1, "identity", nil
673			}
674			numerator, denominator, err := parseRateFraction(declared, field)
675			if err != nil {
676				return 0, 0, "", err
677			}
678			if numerator != denominator {
679				return 0, 0, "", ValidationError(
680					"%s must be omitted or exactly 1 because %s is the functional currency",
681					field, currency,
682				)
683			}
684			return 1, 1, "identity", nil
685		}
686		if declared != "" {
687			numerator, denominator, err := parseRateFraction(declared, field)
688			if err != nil {
689				return 0, 0, "", err
690			}
691			return numerator, denominator, "declared", nil
692		}
693		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
694			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
695		}
696		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
697			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
698		}
699		return 0, 0, "", ValidationError(
700			"no %s/%s exchange rate snapshot exists on or before %s",
701			currency, s.functionalCurrency, date,
702		)
703	}
