728	// CreateStatement imports one bank statement.
729	func (s *Service) CreateStatement(body []byte, key string) (any, error) {
730		var request createStatementRequest
731		if err := decodeObject(body, &request); err != nil {
732			return nil, err
733		}
734		id, err := validateIdentifier(request.ID, "statement id")
735		if err != nil {
736			return nil, err
737		}
738		accountID, err := validateIdentifier(request.AccountID, "account_id")
739		if err != nil {
740			return nil, err
741		}
742		currency, err := validateCurrency(request.Currency, "currency", false)
743		if err != nil {
744			return nil, err
745		}
746		start, err := validateDate(request.Period.Start, "period.start")
747		if err != nil {
748			return nil, err
749		}
750		end, err := validateDate(request.Period.End, "period.end")
751		if err != nil {
752			return nil, err
753		}
754		if start > end {
755			return nil, ValidationError("period.start must not be after period.end")
756		}
757		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
758		if err != nil {
759			return nil, err
760		}
761		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
762		if err != nil {
763			return nil, err
764		}
765		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
766			if _, found := state.Statements[id]; found {
767				return nil, ConflictError("statement %s already exists", id)
768			}
769			account, found := state.Accounts[accountID]
770			if !found {
771				return nil, ValidationError("account_id %s does not exist", accountID)
772			}
773			if currency == "" {
774				currency = account.Currency
775			}
776			if currency != account.Currency {
777				return nil, ValidationError(
778					"currency %s must match the currency %s of account %s",
779					currency, account.Currency, accountID,
780				)
781			}
782			statement := &Statement{
783				ID:                  id,
784				AccountID:           accountID,
785				Currency:            currency,
786				Period:              Period{Start: start, End: end},
787				OpeningBalanceMinor: opening,
788				ClosingBalanceMinor: closing,
789				Lines:               []*StatementLine{},
790				CreatedAt:           s.now(),
791			}
792			total := opening
793			seen := map[string]bool{}
794			for position, raw := range request.Lines {
795				if raw == nil {
796					return nil, ValidationError("lines[%d] must be an object", position+1)
797				}
798				field := fmt.Sprintf("lines[%d]", position+1)
799				lineID, err := validateIdentifier(raw.ID, field+".id")
800				if err != nil {
801					return nil, err
802				}
803				if seen[lineID] {
804					return nil, ValidationError("statement line id %s is duplicated", lineID)
805				}
806				seen[lineID] = true
807				lineDate, err := validateDate(raw.Date, field+".date")
808				if err != nil {
809					return nil, err
810				}
811				if lineDate < start || lineDate > end {
812					return nil, ValidationError("%s.date must fall inside the statement period", field)
813				}
814				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
815				if err != nil {
816					return nil, err
817				}
818				reference, err := validateText(raw.Reference, field+".reference")
819				if err != nil {
820					return nil, err
821				}
822				description, err := validateText(raw.Description, field+".description")
823				if err != nil {
824					return nil, err
825				}
826				total += amount
827				statement.Lines = append(statement.Lines, &StatementLine{
828					ID:          lineID,
829					Date:        lineDate,
830					AmountMinor: amount,
831					Reference:   reference,
832					Description: description,
833				})
834			}
835			if total != closing {
836				return nil, ValidationError(
837					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
838					opening, total-opening, total, closing,
839				)
840			}
841			state.Statements[id] = statement
842			return statement, nil
843		})
844	}
