904	
905	// ledgerEntry is one journal line seen from the ledger side of a
906	// reconciliation. AmountMinor is signed with debits positive.
907	type ledgerEntry struct {
908		ID          string
909		Date        string
910		AmountMinor int64
911		Reference   string
912	}
913	
914	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
915		entries := []*ledgerEntry{}
916		for _, journal := range sortedJournals(state) {
917			if journal.Date < period.Start || journal.Date > period.End {
918				continue
919			}
920			for _, line := range journal.Lines {
921				if line.AccountID != accountID {
922					continue
923				}
924				amount := line.AmountMinor
925				if line.Side == "credit" {
926					amount = -amount
927				}
928				entries = append(entries, &ledgerEntry{
929					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
930					Date:        journal.Date,
931					AmountMinor: amount,
932					Reference:   line.Reference,
933				})
934			}
935		}
936		return entries
937	}
938	
939	var differenceOrder = map[string]int{
940		"timing":               0,
941		"amount_mismatch":      1,
942		"missing_in_ledger":    2,
943		"missing_in_statement": 3,
944	}
945	
946	// computeReconciliation matches statement lines to ledger lines in three
947	// deterministic tiers and classifies everything that stays unmatched.
948	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
949		lines := make([]*StatementLine, 0, len(statement.Lines))
950		lines = append(lines, statement.Lines...)
951		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
952	
953		entries := ledgerEntries(state, statement.AccountID, statement.Period)
954		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
955	
956		statementUsed := make([]bool, len(lines))
957		ledgerUsed := make([]bool, len(entries))
958		differences := []*Difference{}
959		matched := 0
960		match := func(statementIndex, ledgerIndex int, difference *Difference) {
961			statementUsed[statementIndex] = true
962			ledgerUsed[ledgerIndex] = true
963			matched++
964			if difference != nil {
965				differences = append(differences, difference)
966			}
967		}
968	
969		// Tier 1: same signed amount and same date.
970		for index, line := range lines {
971			for other, entry := range entries {
972				if ledgerUsed[other] {
973					continue
974				}
975				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
976					match(index, other, nil)
977					break
978				}
979			}
980		}
981	
982		// Tier 2: same signed amount, different date, so it only differs in timing.
983		for index, line := range lines {
984			if statementUsed[index] {
985				continue
986			}
987			for other, entry := range entries {
988				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
989					continue
990				}
991				statementAmount := line.AmountMinor
992				ledgerAmount := entry.AmountMinor
993				match(index, other, &Difference{
994					Type:                 "timing",
995					Detail:               "the amounts agree but the ledger date differs from the statement date",
996					StatementLineID:      line.ID,
997					LedgerLineID:         entry.ID,
998					StatementDate:        line.Date,
999					LedgerDate:           entry.Date,
1000					StatementAmountMinor: &statementAmount,
1001					LedgerAmountMinor:    &ledgerAmount,
1002				})
1003				break
1004			}
1005		}
1006	
1007		// Tier 3: same non-empty reference but a different amount.
1008		for index, line := range lines {
1009			if statementUsed[index] || line.Reference == "" {
1010				continue
1011			}
1012			for other, entry := range entries {
1013				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
1014					continue
1015				}
1016				statementAmount := line.AmountMinor
1017				ledgerAmount := entry.AmountMinor
1018				match(index, other, &Difference{
1019					Type:                 "amount_mismatch",
1020					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
1021					StatementLineID:      line.ID,
1022					LedgerLineID:         entry.ID,
1023					StatementDate:        line.Date,
1024					LedgerDate:           entry.Date,
1025					StatementAmountMinor: &statementAmount,
1026					LedgerAmountMinor:    &ledgerAmount,
1027					DifferenceMinor:      statementAmount - ledgerAmount,
1028				})
1029				break
1030			}
1031		}
1032	
1033		// Everything still unmatched is missing on one side.
1034		for index, line := range lines {
1035			if statementUsed[index] {
1036				continue
1037			}
1038			amount := line.AmountMinor
1039			differences = append(differences, &Difference{
1040				Type:                 "missing_in_ledger",
1041				Detail:               "the statement line has no journal line in the period",
1042				StatementLineID:      line.ID,
1043				StatementDate:        line.Date,
1044				StatementAmountMinor: &amount,
1045				DifferenceMinor:      amount,
1046			})
1047		}
1048		for index, entry := range entries {
1049			if ledgerUsed[index] {
1050				continue
1051			}
1052			amount := entry.AmountMinor
1053			differences = append(differences, &Difference{
1054				Type:              "missing_in_statement",
1055				Detail:            "the journal line has no statement line in the period",
1056				LedgerLineID:      entry.ID,
1057				LedgerDate:        entry.Date,
1058				LedgerAmountMinor: &amount,
1059				DifferenceMinor:   -amount,
1060			})
1061		}
1062	
1063		sort.SliceStable(differences, func(left, right int) bool {
1064			a, b := differences[left], differences[right]
1065			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1066				return differenceOrder[a.Type] < differenceOrder[b.Type]
1067			}
1068			if a.StatementLineID != b.StatementLineID {
1069				return a.StatementLineID < b.StatementLineID
1070			}
1071			return a.LedgerLineID < b.LedgerLineID
1072		})
1073	
1074		var ledgerNet int64
1075		for _, entry := range entries {
1076			ledgerNet += entry.AmountMinor
1077		}
1078		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1079	
1080		summary := DifferenceSummary{}
1081		var explained int64
1082		for _, difference := range differences {
1083			explained += difference.DifferenceMinor
1084			switch difference.Type {
1085			case "timing":
1086				summary.Timing++
1087			case "amount_mismatch":
1088				summary.AmountMismatch++
1089			case "missing_in_ledger":
1090				summary.MissingInLedger++
1091			case "missing_in_statement":
1092				summary.MissingInStatement++
1093			default:
1094				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1095			}
1096		}
1097		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1098			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1099		}
1100		if explained != statementNet-ledgerNet {
1101			return nil, InternalError("reconciliation differences do not add up to the period difference")
1102		}
1103	
1104		status := "balanced"
1105		if len(differences) > 0 {
1106			status = "differences_found"
1107		}
1108		return &Reconciliation{
1109			ID:                 id,
1110			StatementID:        statement.ID,
1111			AccountID:          statement.AccountID,
1112			Currency:           statement.Currency,
1113			FunctionalCurrency: s.functionalCurrency,
1114			Period:             statement.Period,
1115			Status:             status,
1116			MatchedCount:       matched,
1117			StatementLineCount: len(lines),
1118			LedgerLineCount:    len(entries),
1119			StatementNetMinor:  statementNet,
1120			LedgerNetMinor:     ledgerNet,
1121			DifferenceMinor:    statementNet - ledgerNet,
1122			Summary:            summary,
1123			Differences:        differences,
1124			CreatedAt:          createdAt,
1125		}, nil
1126	}
1127	
1128	func sortedAccounts(state *State) []*Account {
1129		accounts := make([]*Account, 0, len(state.Accounts))
1130		for _, account := range state.Accounts {
1131			accounts = append(accounts, account)
1132		}
1133		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1134		return accounts
1135	}
1136	
1137	func sortedJournals(state *State) []*Journal {
1138		journals := make([]*Journal, 0, len(state.Journals))
1139		for _, journal := range state.Journals {
1140			journals = append(journals, journal)
1141		}
1142		sort.Slice(journals, func(left, right int) bool {
1143			if journals[left].Date != journals[right].Date {
1144				return journals[left].Date < journals[right].Date
1145			}
1146			return journals[left].ID < journals[right].ID
1147		})
1148		return journals
1149	}
1150	
1151	func sortedRates(state *State) []*Rate {
1152		rates := make([]*Rate, 0, len(state.Rates))
1153		rates = append(rates, state.Rates...)
1154		sort.Slice(rates, func(left, right int) bool {
1155			a, b := rates[left], rates[right]
1156			if a.Base != b.Base {
1157				return a.Base < b.Base
1158			}
1159			if a.Quote != b.Quote {
1160				return a.Quote < b.Quote
1161			}
1162			return a.Date < b.Date
1163		})
1164		return rates
1165	}
1166	
1167	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1168		nodes := map[string]*AccountNode{}
1169		for _, account := range state.Accounts {
1170			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1171		}
1172		roots := []*AccountNode{}
1173		for _, account := range sortedAccounts(state) {
1174			node := nodes[account.ID]
1175			if account.ParentID == nil {
1176				roots = append(roots, node)
1177				continue
1178			}
1179			parent, found := nodes[*account.ParentID]
1180			if !found {
1181				roots = append(roots, node)
1182				continue
1183			}
1184			parent.Children = append(parent.Children, node)
1185		}
1186		return nodes, roots
1187	}
1188	
1189	// latestRate returns the most recent snapshot for one direction that is
1190	// effective on the given date.
1191	func latestRate(state *State, base, quote, asOf string) *Rate {
1192		var best *Rate
1193		for _, rate := range state.Rates {
1194			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1195				continue
1196			}
1197			if best == nil || rate.Date > best.Date {
1198				best = rate
1199			}
1200		}
