1	package reconcore
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"sync"
8	)
9	
10	// State is the complete database. It is small enough to live in memory and to
11	// be rewritten atomically as one JSON document after every mutation, which is
12	// what replaces a real database driver in this standard-library-only build.
13	type State struct {
14		Accounts        map[string]*Account           `json:"accounts"`
15		Journals        map[string]*Journal           `json:"journals"`
16		Rates           []*Rate                       `json:"rates"`
17		Statements      map[string]*Statement         `json:"statements"`
18		Reconciliations map[string]*Reconciliation    `json:"reconciliations"`
19		PeriodCloses    map[string]*PeriodClose       `json:"period_closes"`
20		Idempotency     map[string]*IdempotencyRecord `json:"idempotency"`
21	}
22	
23	func newState() *State {
24		return &State{
25			Accounts:        map[string]*Account{},
26			Journals:        map[string]*Journal{},
27			Rates:           []*Rate{},
28			Statements:      map[string]*Statement{},
29			Reconciliations: map[string]*Reconciliation{},
30			PeriodCloses:    map[string]*PeriodClose{},
31			Idempotency:     map[string]*IdempotencyRecord{},
32		}
33	}
34	
35	// Store owns the in-memory state and its file. Every mutation runs against a
36	// copy that is persisted first, so a failed write never changes the process
37	// state and no reader ever sees a half-applied transaction.
38	type Store struct {
39		path  string
40		mutex sync.Mutex
41		state *State
42	}
43	
44	// OpenStore loads the database at path, creating it on first write.
45	func OpenStore(path string) (*Store, error) {
46		if path == "" {
47			path = "reconcore.db"
48		}
49		state := newState()
50		contents, err := os.ReadFile(path)
51		switch {
52		case err == nil:
53			if err := json.Unmarshal(contents, state); err != nil {
54				return nil, InternalError("database %s is not readable JSON: %s", path, err)
55			}
56			state.repair()
57		case os.IsNotExist(err):
58		default:
59			return nil, InternalError("database %s could not be read: %s", path, err)
60		}
61		return &Store{path: path, state: state}, nil
62	}
63	
64	func (s *State) repair() {
65		if s.Accounts == nil {
66			s.Accounts = map[string]*Account{}
67		}
68		if s.Journals == nil {
69			s.Journals = map[string]*Journal{}
70		}
71		if s.Rates == nil {
72			s.Rates = []*Rate{}
73		}
74		if s.Statements == nil {
75			s.Statements = map[string]*Statement{}
76		}
77		if s.Reconciliations == nil {
78			s.Reconciliations = map[string]*Reconciliation{}
79		}
80		if s.PeriodCloses == nil {
81			s.PeriodCloses = map[string]*PeriodClose{}
82		}
83		if s.Idempotency == nil {
84			s.Idempotency = map[string]*IdempotencyRecord{}
85		}
86	}
87	
88	// Update runs mutate against a copy of the state and commits it on success.
89	func (s *Store) Update(mutate func(state *State) error) error {
90		s.mutex.Lock()
91		defer s.mutex.Unlock()
92		clone, err := cloneState(s.state)
93		if err != nil {
94			return err
95		}
96		if err := mutate(clone); err != nil {
97			return err
98		}
99		if err := writeState(s.path, clone); err != nil {
100			return err
101		}
102		s.state = clone
103		return nil
104	}
105	
106	// View runs read against the committed state under the store lock.
107	func (s *Store) View(read func(state *State) (any, error)) (any, error) {
108		s.mutex.Lock()
109		defer s.mutex.Unlock()
110		return read(s.state)
111	}
112	
113	func cloneState(state *State) (*State, error) {
114		encoded, err := json.Marshal(state)
115		if err != nil {
116			return nil, InternalError("database could not be serialised: %s", err)
117		}
118		clone := newState()
119		if err := json.Unmarshal(encoded, clone); err != nil {
120			return nil, InternalError("database could not be restored: %s", err)
121		}
122		return clone, nil
123	}
124	
125	func writeState(path string, state *State) error {
126		encoded, err := json.MarshalIndent(state, "", "  ")
127		if err != nil {
128			return InternalError("database could not be serialised: %s", err)
129		}
130		encoded = append(encoded, '\n')
131		if directory := filepath.Dir(path); directory != "" && directory != "." {
132			if err := os.MkdirAll(directory, 0o755); err != nil {
133				return InternalError("database directory could not be created: %s", err)
134			}
135		}
136		temporary := path + ".tmp"
137		if err := os.WriteFile(temporary, encoded, 0o644); err != nil {
138			return InternalError("database could not be written: %s", err)
139		}
140		if err := os.Rename(temporary, path); err != nil {
141			return InternalError("database could not be committed: %s", err)
142		}
143		return nil
144	}
145

