58	func (c *client) send(r request) (int, string, map[string]any) {
59		c.t.Helper()
60		var body io.Reader
61		if r.body != "" {
62			body = bytes.NewBufferString(r.body)
63		}
64		httpRequest, err := http.NewRequest(r.method, c.server.URL+r.path, body)
65		if err != nil {
66			c.t.Fatalf("build request: %v", err)
67		}
68		if !r.omitType {
69			contentType := r.contentType
70			if contentType == "" {
71				contentType = "application/json"
72			}
73			httpRequest.Header.Set("Content-Type", contentType)
74		}
75		if r.key != "" {
76			httpRequest.Header.Set("Idempotency-Key", r.key)
77		}
78		response, err := c.server.Client().Do(httpRequest)
79		if err != nil {
80			c.t.Fatalf("%s %s: %v", r.method, r.path, err)
81		}
82		defer response.Body.Close()
83		raw, err := io.ReadAll(response.Body)
84		if err != nil {
85			c.t.Fatalf("read %s %s: %v", r.method, r.path, err)
86		}
87		decoded := map[string]any{}
88		if len(raw) > 0 {
89			if err := json.Unmarshal(raw, &decoded); err != nil {
90				c.t.Fatalf("%s %s returned non-object JSON %s", r.method, r.path, raw)
91			}
92		}
93		return response.StatusCode, string(raw), decoded
94	}
